INSERT OR IGNORE INTO events(id,slug,title,draft_json,created_at,updated_at) VALUES('first-seat','first-seat','FIRST SEAT','{"id":"first-seat","slug":"first-seat","title":"FIRST SEAT","description":"서울아레나의 첫 번째 문장을 함께 만들어주세요.","visibility":"draft","template":"first-seat","updatedAt":"","maxLength":30,"allowRepeatVotes":false,"pages":{"submission":[{"id":"hero","type":"hero","title":"서울아레나, 첫 좌석에 새길 한 문장을 보내주세요.","body":"18,269개의 좌석 중 가장 먼저 자리를 잡게 될 단 하나의 좌석, First Seat.\n무대도, 조명도 채워지지 않은 지금. 가장 먼저 완성되는 것은 관객의 자리입니다.\n서울아레나는 그 첫 좌석에 새길 문구를 대중과 함께 완성하려 합니다. 당신이 남긴 한 문장이, 서울아레나의 첫 기록이 됩니다.","titleSize":"body","titleTone":"emphasis","bodyTone":"default"},{"id":"form","type":"form","title":"","body":"","titleSize":"h3","titleTone":"emphasis","bodyTone":"default"},{"id":"consent","type":"consent","title":"참여를 위해 확인해주세요.","body":"수집 항목: 이름, 연락처, 이메일\n수집 목적: 응모 접수 및 당선 안내\n검토용 예시이며 실제 공개 전 보유기간과 운영 주체를 확정합니다.","titleSize":"h3","titleTone":"emphasis","bodyTone":"default"},{"id":"notices","type":"notices","title":"참여 전 확인해주세요.","body":"직접 작성한 문구만 응모할 수 있습니다.\n타인의 권리를 침해하는 내용은 선정에서 제외될 수 있습니다.\n선정 일정과 안내는 이벤트 페이지에서 확인할 수 있습니다.","titleSize":"h3","titleTone":"emphasis","bodyTone":"default"}],"voting":[{"id":"hero","type":"hero","title":"마음을 움직이는\n한 문장을 골라주세요.","body":"서울아레나의 첫 번째 이야기를 함께 완성해주세요.","titleSize":"body","titleTone":"emphasis","bodyTone":"default"},{"id":"candidates","type":"candidates","title":"당신의 선택은?","body":"가장 공감하는 문구 하나를 선택해주세요.","titleSize":"h3","titleTone":"emphasis","bodyTone":"default"},{"id":"form","type":"form","title":"투표 참여 정보","body":"연락처·이메일·인스타그램을 확인하여 중복 투표를 제한합니다.","titleSize":"h3","titleTone":"emphasis","bodyTone":"default"},{"id":"consent","type":"consent","title":"투표를 위해 확인해주세요.","body":"수집 항목: 연락처, 이메일, 인스타그램 계정\n수집 목적: 투표 운영 및 중복 참여 확인\n검토용 동의문입니다. 실제 공개 전 보유기간과 운영 주체를 확정합니다.","titleSize":"h3","titleTone":"emphasis","bodyTone":"default"}],"result":[{"id":"hero","type":"hero","title":"우리의 첫 문장이\n완성되었습니다.","body":"서울아레나의 시작을 함께해주셔서 감사합니다.","titleSize":"body","titleTone":"emphasis","bodyTone":"default"},{"id":"result","type":"result","title":"함께 만든 첫 번째 이야기","body":"선정된 문구는 결과 공개 후 이곳에 표시됩니다.","titleSize":"h1","titleTone":"emphasis","bodyTone":"default"},{"id":"text","type":"text","title":"다음 순간에도, 함께해요.","body":"서울아레나의 새로운 소식을 기다려주세요.","titleSize":"h4","titleTone":"default","bodyTone":"default"}]},"contactUrl":"mailto:marketing.1@seoularena.net","privacyPolicy":"","retentionDays":90}',unixepoch()*1000,unixepoch()*1000);
